// Generated by Lienzo UI. Runtime helper shared by every design: do not edit by hand.
// Fits its RectTransform to Screen.safeArea (notch, rounded corners, home indicator).
using UnityEngine;

/// Put on a stretched child container of a Canvas: the container follows the device safe area.
[ExecuteAlways]
[DisallowMultipleComponent]
[RequireComponent(typeof(RectTransform))]
public class LienzoSafeArea : MonoBehaviour
{
    Rect lastArea;
    Vector2Int lastScreen;

    void OnEnable() => Refresh();

    void Update()
    {
        if (Screen.safeArea != lastArea || Screen.width != lastScreen.x || Screen.height != lastScreen.y) Refresh();
    }

    void OnRectTransformDimensionsChange()
    {
        if (isActiveAndEnabled) Refresh();
    }

    /// Recomputes the anchors from Screen.safeArea.
    public void Refresh()
    {
        var rt = (RectTransform)transform;
        var area = Screen.safeArea;
        lastArea = area;
        lastScreen = new Vector2Int(Screen.width, Screen.height);
        if (Screen.width <= 0 || Screen.height <= 0) return;
        var min = area.position;
        var max = area.position + area.size;
        min.x /= Screen.width;
        min.y /= Screen.height;
        max.x /= Screen.width;
        max.y /= Screen.height;
        rt.anchorMin = min;
        rt.anchorMax = max;
        rt.offsetMin = Vector2.zero;
        rt.offsetMax = Vector2.zero;
    }
}
